class Solution:
    def fillCups(self, amount: list[int]) -> int:
        return max(max(amount), (sum(amount) + 1) // 2)

class Solution {
public:
    int fillCups(std::vector<int>& amount) {
        int mx = std::max({amount[0], amount[1], amount[2]});
        int sum = amount[0] + amount[1] + amount[2];
        return std::max(mx, (sum + 1) / 2);
    }
};

class Solution {
    public int fillCups(int[] amount) {
        int mx = Math.max(amount[0], Math.max(amount[1], amount[2]));
        int sum = amount[0] + amount[1] + amount[2];
        return Math.max(mx, (sum + 1) / 2);
    }
}

var fillCups = function(amount) {
    const mx = Math.max(...amount);
    const sum = amount[0] + amount[1] + amount[2];
    return Math.max(mx, Math.ceil(sum / 2));
};
